import {escapeHtml as e,avatar,uiIcons,imageSrc} from './ui.js';
import {preparePostImage} from './image-editor.js';
let draft={text:'',kind:'post',topic:'general'},draftOwner=null;
const formats=[['post','Gedanke','✦'],['collab','Collab gesucht','✧'],['stream','Stream-Ankündigung','▷']];
export function composerTeaser(profile){return `<section class="compose-teaser" aria-label="Beitrag erstellen">${avatar(profile)}<button id="composeOpen"><span>Was möchtest du teilen?</span><small>Ein Gedanke, ein Projekt oder deine nächste Collab.</small></button><button class="compose-quick" id="quickPost" aria-label="Beitrag erstellen">${uiIcons.pen}</button></section>`}
export function openComposer({profile,onPublish,topic='general'}){
 if(draftOwner!==profile.id){draftOwner=profile.id;draft={text:'',kind:'post',topic}}
 if(!draft.text&&!draft.imageUpload)draft.topic=topic;
 let dialog=document.querySelector('#postDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='postDialog';document.body.append(dialog)}
 dialog.innerHTML=`<form class="post-editor"><div class="post-editor-header"><div><span class="eyebrow">TEILE, WAS DICH BEWEGT</span><h2>Neuer Beitrag</h2></div><button type="button" class="icon-control" id="closeComposer" aria-label="Beitragseditor schließen">${uiIcons.close}</button></div><div class="post-editor-author">${avatar(profile)}<div><strong>${e(profile.name)}</strong><small>Für alle auf VConnect sichtbar</small></div></div><fieldset class="post-formats"><legend class="sr-only">Beitragsart</legend>${formats.map(([key,label,icon])=>`<label><input type="radio" name="kind" value="${key}" ${draft.kind===key?'checked':''}><span>${icon} ${label}</span></label>`).join('')}</fieldset><label class="post-topic">Bereich<select name="topic">${[['general','Community'],['art','Art · Künstler'],['design','Design · Programmierung']].map(([value,label])=>`<option value="${value}" ${draft.topic===value?'selected':''}>${label}</option>`).join('')}</select></label><textarea id="composerText" name="text" maxlength="500" placeholder="${draft.topic==='art'?'Zeig deine Arbeit oder teile eine kreative Idee.':draft.topic==='design'?'Woran arbeitest du? Teile ein Projekt, Code oder eine Frage.':'Was passiert in deiner Welt?'}" aria-label="Beitragstext">${e(draft.text)}</textarea><div id="postAttachment"></div><div class="attachment-tools"><label class="attach-image"><input id="postImageFile" type="file" accept="image/png,image/jpeg,image/webp"><span>▧ Bild hinzufügen</span></label><button id="insertCode" type="button">&lt;/&gt; Code einfügen</button><span id="uploadStatus" role="status"></span></div><div class="composer-guidance"><span id="formatHint"></span><span id="charCount" aria-label="Zeichenanzahl">${draft.text.length}/500</span></div><p id="postError" role="alert"></p><div class="post-editor-footer"><span>Entwurf bleibt bis zum Neuladen erhalten.</span><button class="publish-button" id="publishPost" type="submit"><span>Veröffentlichen</span>${uiIcons.arrow}</button></div></form>`;
 const form=dialog.querySelector('form'),text=dialog.querySelector('textarea'),submit=dialog.querySelector('#publishPost');let imagePending=false;
 function update(){draft={...draft,text:text.value,kind:form.elements.kind.value,topic:form.elements.topic.value,imageAlt:form.elements.imageAlt?.value||draft.imageAlt||''};dialog.querySelector('#charCount').textContent=text.value.length+'/500';dialog.querySelector('#charCount').classList.toggle('near-limit',text.value.length>450);submit.disabled=imagePending||(!text.value.trim()&&!draft.imageUpload);text.required=!draft.imageUpload;dialog.querySelector('#insertCode').hidden=draft.topic!=='design';const hints={post:draft.topic==='art'?'Eigene Arbeiten teilen. Credits für Arbeiten anderer nicht vergessen.':'Teile einen Gedanken mit der Community.',collab:'Hilfreich: Thema, Sprache und ein passender Zeitraum.',stream:'Teile Thema, Startzeit und den Link zu deinem Stream.'};dialog.querySelector('#formatHint').textContent=hints[draft.kind]}
 function attachment(){const target=dialog.querySelector('#postAttachment');target.innerHTML=draft.imageUpload?`<div class="attachment-preview"><img src="${e(draft.imageUpload)}" alt="Bildvorschau"><button id="removePostImage" type="button" class="icon-control" aria-label="Bild entfernen">${uiIcons.close}</button></div><label class="image-alt-label">Bildbeschreibung · optional<input name="imageAlt" maxlength="200" value="${e(draft.imageAlt||'')}" placeholder="Beschreibe das Bild für Menschen mit Screenreader."></label>`:'';if(target.querySelector('#removePostImage'))target.querySelector('#removePostImage').onclick=()=>{delete draft.imageUpload;draft.imageAlt='';attachment();update()}}
 dialog.querySelector('#postImageFile').onchange=async event=>{const input=event.target;if(!input.files?.[0]||imagePending)return;imagePending=true;update();dialog.querySelector('#uploadStatus').textContent='Bild wird vorbereitet …';try{const prepared=await preparePostImage(input.files[0]);draft={...draft,imageUpload:prepared};attachment();dialog.querySelector('#postError').textContent=''}catch(error){dialog.querySelector('#postError').textContent=error.message}finally{imagePending=false;input.value='';dialog.querySelector('#uploadStatus').textContent='';update()}};
 dialog.querySelector('#insertCode').onclick=()=>{const block='\n```js\n// Dein Code\n```\n';if(text.value.length+block.length>500){dialog.querySelector('#postError').textContent='Für einen Codeblock ist nicht mehr genügend Platz.';return}text.setRangeText(block,text.selectionStart,text.selectionEnd,'end');text.focus();update()};
 form.oninput=update;form.onchange=update;dialog.querySelector('#closeComposer').onclick=()=>dialog.close();
 form.onsubmit=async event=>{event.preventDefault();if(imagePending||(!text.value.trim()&&!draft.imageUpload))return;submit.disabled=true;submit.querySelector('span').textContent='Wird veröffentlicht …';try{await onPublish({...draft});draft={text:'',kind:'post',topic:'general'};dialog.close()}catch(error){dialog.querySelector('#postError').textContent=error.message;submit.disabled=false;submit.querySelector('span').textContent='Veröffentlichen'}};
 text.onkeydown=event=>{if((event.ctrlKey||event.metaKey)&&event.key==='Enter'){event.preventDefault();if(!submit.disabled)form.requestSubmit()}};attachment();update();dialog.showModal();text.focus();
}
export function formatPostText(text){return String(text||'').split(/(```[\s\S]*?```)/g).filter(Boolean).map(part=>{if(part.startsWith('```')){const content=part.slice(3,-3),line=content.indexOf('\n'),code=line>=0?content.slice(line+1):content;return `<pre class="post-code"><code>${e(code.replace(/\n$/,''))}</code></pre>`}return `<p class="post-text">${e(part)}</p>`}).join('')}
export function postMarkup(post,author,{saved=false,own=false}={}){
 const age=Math.max(0,Date.now()-post.date),label=age<60000?'Gerade eben':age<3600000?Math.floor(age/60000)+' Min.':age<86400000?Math.floor(age/3600000)+' Std.':new Date(post.date).toLocaleDateString('de-DE',{day:'numeric',month:'short'});
 const kind=formats.find(f=>f[0]===post.kind),image=imageSrc(post.image);
 return `<article class="post feed-post"><button class="author-avatar" data-profile="${e(post.author)}" aria-label="Profil von ${e(author?.name||'Creator')} öffnen">${avatar(author)}</button><div class="post-body"><div class="post-heading"><button data-profile="${e(post.author)}" class="author-name">${e(author?.name||'Creator')}</button>${own?'<span class="own-label">Du</span>':''}<time datetime="${new Date(post.date).toISOString()}" title="${e(new Date(post.date).toLocaleString('de-DE'))}">${e(label)}</time></div><div class="post-author-detail">${author?.username?'@'+e(author.username)+' · ':''}${e(author?.role||'Community')}${author?.pronouns?' · '+e(author.pronouns):''}</div>${kind&&post.kind!=='post'?`<span class="post-kind kind-${post.kind}">${kind[2]} ${kind[1]}</span>`:''}${['art','design'].includes(post.topic)?`<button class="post-topic-badge" data-page="${post.topic==='art'?'Art':'Design'}">${post.topic==='art'?'Art':'Design'} ↗</button>`:''}${formatPostText(post.text)}${image?`<a class="post-image-link" href="${e(image)}" target="_blank" rel="noopener noreferrer"><img src="${e(image)}" alt="${e(post.image_alt||'Geteiltes Bild')}" loading="lazy" decoding="async"></a>`:''}<div class="post-actions"><button data-like="${e(post.id)}" class="like-action ${post.liked?'is-liked':''}" aria-label="Gefällt mir" aria-pressed="${post.liked}">${uiIcons.heart}<span>${post.likes||0}</span></button><button data-save="${e(post.id)}" class="save-action ${saved?'is-saved':''}" aria-label="Lesezeichen" aria-pressed="${saved}">${uiIcons.bookmark}<span>${saved?'Gespeichert':'Merken'}</span></button><button data-share="${e(post.id)}" aria-label="Beitrag kopieren">${uiIcons.share}<span>Kopieren</span></button></div></div></article>`;
}
